  1	import { Flex, Separator, Spacer, Text } from "@artsy/palette";
  2	import type { GetServerSideProps } from "next";
  3	import Head from "next/head";
  4	import Link from "next/link";
  5	import styled from "styled-components";
  6	import { SiteCard } from "../components/SiteCard";
  7	import { SiteLink } from "../components/SiteLink";
  8	import { SiteTable } from "../components/SiteTable";
  9	import { getConfig, getS3Client } from "../lib/deps";
 10	import {
 11	  DEFAULT_SITE_SORT,
 12	  parseSiteSort,
 13	  type SiteListing,
 14	  toSiteListing,
 15	} from "../lib/siteListing";
 16	import { listSites, type SiteSort } from "../lib/sites";
 17	
 18	type SiteView = "list" | "grid";
 19	
 20	// One width for both views, so the controls stay put when switching.
 21	const PAGE_MAX_WIDTH = "1440px";
 22	
 23	// Below this the count is hidden so the sort and view controls share a line.
 24	const SMALL_SCREEN = "599px";
 25	
 26	// Below this even the controls need the room, so their labels are hidden
 27	// visually (still announced by screen readers).
 28	const NARROW_PHONE = "439px";
 29	
 30	// Roughly the first two rows on a desktop-width grid.
 31	const EAGER_THUMBNAILS = 10;
 32	
 33	interface SitesPageProps {
 34	  sites: SiteListing[];
 35	  sort: SiteSort;
 36	  view: SiteView;
 37	}
 38	
 39	const SORT_OPTIONS: Array<{ sort: SiteSort; label: string }> = [
 40	  { sort: "newest", label: "Newest" },
 41	  { sort: "name", label: "Name" },
 42	  { sort: "uploader", label: "Uploader" },
 43	];
 44	
 45	const VIEW_OPTIONS: Array<{ view: SiteView; label: string }> = [
 46	  { view: "grid", label: "Grid" },
 47	  { view: "list", label: "List" },
 48	];
 49	
 50	function parseView(value: unknown): SiteView {
 51	  return value === "list" ? "list" : "grid";
 52	}
 53	
 54	// The grid view is the default, so it stays out of the URL.
 55	function sitesHref(sort: SiteSort, view: SiteView): string {
 56	  const params = new URLSearchParams({ sort });
 57	  if (view === "list") {
 58	    params.set("view", "list");
 59	  }
 60	  return `/sites?${params}`;
 61	}
 62	
 63	const OptionLink = styled(Link)`
 64	  color: inherit;
 65	  text-decoration: none;
 66	  padding: 0.125rem 0.25rem;
 67	  border-radius: 4px;
 68	  transition: background-color 0.15s ease;
 69	
 70	  &:hover {
 71	    background-color: color-mix(in srgb, currentColor 12%, transparent);
 72	  }
 73	
 74	  &[aria-current="true"] {
 75	    text-decoration: underline;
 76	  }
 77	`;
 78	
 79	interface OptionLinksProps {
 80	  label: string;
 81	  options: Array<{ label: string; href: string; active: boolean }>;
 82	}
 83	
 84	const SiteCount = styled(Text)`
 85	  white-space: nowrap;
 86	
 87	  @media (max-width: ${SMALL_SCREEN}) {
 88	    display: none;
 89	  }
 90	`;
 91	
 92	const ControlLabel = styled(Text)`
 93	  @media (max-width: ${NARROW_PHONE}) {
 94	    position: absolute;
 95	    width: 1px;
 96	    height: 1px;
 97	    overflow: hidden;
 98	    clip: rect(0 0 0 0);
 99	    white-space: nowrap;
100	  }
101	`;
102	
103	function OptionLinks({ label, options }: OptionLinksProps) {
104	  return (
105	    <>
106	      <ControlLabel variant="sm" fontWeight="bold" mr={0.5}>
107	        {label}
108	      </ControlLabel>
109	      {options.map((option) => (
110	        <Text key={option.label} variant="sm">
111	          <OptionLink href={option.href} aria-current={option.active ? "true" : undefined}>
112	            {option.label}
113	          </OptionLink>
114	        </Text>
115	      ))}
116	    </>
117	  );
118	}
119	
120	// Equal-width side groups that never squeeze below their content, so the
121	// header wraps group by group on narrow screens instead of breaking a label.
122	const SIDE_GROUP_STYLE = { flex: "1 1 0", minWidth: "max-content", whiteSpace: "nowrap" } as const;
123	
124	export const getServerSideProps: GetServerSideProps<SitesPageProps> = async ({ query }) => {
125	  const sort = parseSiteSort(query.sort) ?? DEFAULT_SITE_SORT;
126	  const { s3Bucket } = getConfig();
127	  const sites = await listSites(getS3Client(), s3Bucket, sort);
128	
129	  return {
130	    props: {
131	      sort,
132	      view: parseView(query.view),
133	      sites: sites.map((site) => toSiteListing(site)),
134	    },
135	  };
136	};
137	
138	export default function SitesPage({ sites, sort, view }: SitesPageProps) {
139	  return (
140	    <>
141	      <Head>
142	        <title>Sites | Atelier</title>
143	      </Head>
144	
145	      <Flex flexDirection="column" width="100%" maxWidth={PAGE_MAX_WIDTH} mx="auto" p={2} mt={4}>
146	        <Text as="h1" variant="xl">
147	          Atelier Sites
148	        </Text>
149	
150	        <Spacer y={2} />
151	
152	        {sites.length > 0 && (
153	          <>
154	            <Flex alignItems="baseline" flexWrap="wrap" style={{ gap: "0.5rem 1rem" }}>
155	              <Flex alignItems="baseline" style={SIDE_GROUP_STYLE}>
156	                <OptionLinks
157	                  label="Sort by"
158	                  options={SORT_OPTIONS.map((option) => ({
159	                    label: option.label,
160	                    href: sitesHref(option.sort, view),
161	                    active: option.sort === sort,
162	                  }))}
163	                />
164	              </Flex>
165	
166	              <SiteCount variant="sm" fontWeight="bold">
167	                {sites.length} {sites.length === 1 ? "site" : "sites"}
168	              </SiteCount>
169	
170	              <Flex alignItems="baseline" justifyContent="flex-end" style={SIDE_GROUP_STYLE}>
171	                <OptionLinks
172	                  label="View as"
173	                  options={VIEW_OPTIONS.map((option) => ({
174	                    label: option.label,
175	                    href: sitesHref(sort, option.view),
176	                    active: option.view === view,
177	                  }))}
178	                />
179	              </Flex>
180	            </Flex>
181	            <Separator role="separator" my={2} />
182	          </>
183	        )}
184	
185	        {sites.length === 0 ? (
186	          <Text variant="md">No sites yet</Text>
187	        ) : view === "grid" ? (
188	          <ul
189	            style={{
190	              listStyle: "none",
191	              margin: 0,
192	              padding: 0,
193	              display: "grid",
194	              gridTemplateColumns: "repeat(auto-fill, minmax(240px, 1fr))",
195	              rowGap: "2.5rem",
196	              columnGap: "1.5rem",
197	            }}
198	          >
199	            {sites.map((site, index) => (
200	              <li key={site.slug}>
201	                <SiteCard site={site} eager={index < EAGER_THUMBNAILS} />
202	              </li>
203	            ))}
204	          </ul>
205	        ) : (
206	          <SiteTable sites={sites} />
207	        )}
208	
209	        <Spacer y={2} />
210	        <Text variant="md">
211	          <SiteLink href="/">&larr; Upload a site</SiteLink>
212	        </Text>
213	      </Flex>
214	    </>
215	  );
216	}
  1	import { Text } from "@artsy/palette";
  2	import styled from "styled-components";
  3	import { formatUploader } from "../lib/formatAttribution";
  4	import { formatRelativeTime } from "../lib/formatRelativeTime";
  5	import type { SiteListing } from "../lib/siteListing";
  6	import { SiteLink } from "./SiteLink";
  7	import { SiteThumbnail } from "./SiteThumbnail";
  8	
  9	const Table = styled.table`
 10	  width: 100%;
 11	  border-collapse: collapse;
 12	  text-align: left;
 13	`;
 14	
 15	const rowBorder = "1px solid color-mix(in srgb, currentColor 15%, transparent)";
 16	
 17	const THUMBNAIL_WIDTH = 72;
 18	// Eager covers roughly the rows visible without scrolling.
 19	const EAGER_ROWS = 12;
 20	
 21	// Column names for assistive tech only; the layout is self-explanatory.
 22	const VisuallyHiddenHead = styled.thead`
 23	  position: absolute;
 24	  width: 1px;
 25	  height: 1px;
 26	  overflow: hidden;
 27	  clip: rect(0 0 0 0);
 28	  white-space: nowrap;
 29	`;
 30	
 31	const Cell = styled.td`
 32	  padding: 0.5rem 1rem 0.5rem 0;
 33	  border-bottom: ${rowBorder};
 34	  vertical-align: middle;
 35	  overflow-wrap: anywhere;
 36	
 37	  &:last-child {
 38	    padding-right: 0;
 39	  }
 40	`;
 41	
 42	const ThumbnailCell = styled(Cell)`
 43	  width: ${THUMBNAIL_WIDTH}px;
 44	`;
 45	
 46	// Deterministic (not locale-based), so server and client render the same.
 47	function preciseTime(iso: string): string {
 48	  return `${iso.slice(0, 16).replace("T", " ")} UTC`;
 49	}
 50	
 51	export function SiteTable({ sites }: { sites: SiteListing[] }) {
 52	  return (
 53	    <Table>
 54	      <VisuallyHiddenHead>
 55	        <tr>
 56	          {["Preview", "Slug", "Uploaded by", "Uploaded"].map((heading) => (
 57	            <th key={heading} scope="col">
 58	              {heading}
 59	            </th>
 60	          ))}
 61	        </tr>
 62	      </VisuallyHiddenHead>
 63	      <tbody>
 64	        {sites.map((site, index) => {
 65	          const uploader = formatUploader(site.uploadedBy);
 66	          const when = formatRelativeTime(site.uploadedAt);
 67	          return (
 68	            <tr key={site.slug}>
 69	              <ThumbnailCell>
 70	                <div style={{ width: THUMBNAIL_WIDTH }}>
 71	                  <SiteThumbnail
 72	                    site={site}
 73	                    eager={index < EAGER_ROWS}
 74	                    alt=""
 75	                    sizes={`${THUMBNAIL_WIDTH}px`}
 76	                    placeholderText={false}
 77	                  />
 78	                </div>
 79	              </ThumbnailCell>
 80	              <Cell>
 81	                <Text variant="md">
 82	                  <SiteLink
 83	                    href={site.url}
 84	                    target="_blank"
 85	                    rel="noopener noreferrer"
 86	                    textDecoration="none"
 87	                  >
 88	                    {site.slug}
 89	                  </SiteLink>
 90	                </Text>
 91	              </Cell>
 92	              <Cell>
 93	                <Text variant="sm" color="mono60">
 94	                  {uploader ?? "—"}
 95	                </Text>
 96	              </Cell>
 97	              <Cell>
 98	                <Text variant="sm" color="mono60" textAlign="right">
 99	                  {when && site.uploadedAt ? (
100	                    <time dateTime={site.uploadedAt} title={preciseTime(site.uploadedAt)}>
101	                      {when}
102	                    </time>
103	                  ) : (
104	                    "—"
105	                  )}
106	                </Text>
107	              </Cell>
108	            </tr>
109	          );
110	        })}
111	      </tbody>
112	    </Table>
113	  );
114	}
  1	import type { PutObjectCommandInput, S3Client } from "@aws-sdk/client-s3";
  2	import {
  3	  DeleteObjectsCommand,
  4	  GetObjectCommand,
  5	  HeadObjectCommand,
  6	  ListObjectsV2Command,
  7	  PutObjectCommand,
  8	} from "@aws-sdk/client-s3";
  9	import { validateSlug } from "./slug";
 10	
 11	export interface HeadIndexResult {
 12	  exists: boolean;
 13	  uploadedBy?: string;
 14	  uploadedAt?: string;
 15	}
 16	
 17	const DELETE_BATCH_SIZE = 1000;
 18	
 19	function isNotFound(err: unknown): boolean {
 20	  return (
 21	    typeof err === "object" &&
 22	    err !== null &&
 23	    "name" in err &&
 24	    ((err as { name: unknown }).name === "NotFound" ||
 25	      (err as { name: unknown }).name === "NoSuchKey")
 26	  );
 27	}
 28	
 29	// The leading underscore keeps this outside the slug namespace, so a site's
 30	// delete-then-put under `<slug>/` never touches its thumbnail.
 31	function thumbnailKey(slug: string): string {
 32	  return `_thumbnails/${slug}.jpg`;
 33	}
 34	
 35	export async function headIndex(
 36	  client: S3Client,
 37	  bucket: string,
 38	  slug: string,
 39	): Promise<HeadIndexResult> {
 40	  try {
 41	    const result = await client.send(
 42	      new HeadObjectCommand({ Bucket: bucket, Key: `${slug}/index.html` }),
 43	    );
 44	    const uploadedBy = result.Metadata?.["uploaded-by"];
 45	    const uploadedAt = result.Metadata?.["uploaded-at"];
 46	    return {
 47	      exists: true,
 48	      ...(uploadedBy !== undefined && { uploadedBy }),
 49	      ...(uploadedAt !== undefined && { uploadedAt }),
 50	    };
 51	  } catch (err) {
 52	    if (isNotFound(err)) {
 53	      return { exists: false };
 54	    }
 55	    throw err;
 56	  }
 57	}
 58	
 59	export async function listPrefix(
 60	  client: S3Client,
 61	  bucket: string,
 62	  slug: string,
 63	): Promise<string[]> {
 64	  const keys: string[] = [];
 65	  let continuationToken: string | undefined;
 66	
 67	  do {
 68	    const result = await client.send(
 69	      new ListObjectsV2Command({
 70	        Bucket: bucket,
 71	        Prefix: `${slug}/`,
 72	        ContinuationToken: continuationToken,
 73	      }),
 74	    );
 75	    for (const obj of result.Contents ?? []) {
 76	      if (obj.Key) {
 77	        keys.push(obj.Key);
 78	      }
 79	    }
 80	    continuationToken = result.IsTruncated ? result.NextContinuationToken : undefined;
 81	  } while (continuationToken);
 82	
 83	  return keys;
 84	}
 85	
 86	export async function listSlugs(client: S3Client, bucket: string): Promise<string[]> {
 87	  const slugs: string[] = [];
 88	  let continuationToken: string | undefined;
 89	
 90	  do {
 91	    const result = await client.send(
 92	      new ListObjectsV2Command({
 93	        Bucket: bucket,
 94	        Delimiter: "/",
 95	        ContinuationToken: continuationToken,
 96	      }),
 97	    );
 98	    for (const commonPrefix of result.CommonPrefixes ?? []) {
 99	      if (commonPrefix.Prefix) {
100	        const slug = commonPrefix.Prefix.replace(/\/$/, "");
101	        if (validateSlug(slug).valid) {
102	          slugs.push(slug);
103	        }
104	      }
105	    }
106	    continuationToken = result.IsTruncated ? result.NextContinuationToken : undefined;
107	  } while (continuationToken);
108	
109	  return slugs;
110	}
111	
112	export async function deletePrefix(
113	  client: S3Client,
114	  bucket: string,
115	  slug: string,
116	): Promise<number> {
117	  const keys = await listPrefix(client, bucket, slug);
118	  let deletedCount = 0;
119	  const failedKeys: string[] = [];
120	
121	  for (let i = 0; i < keys.length; i += DELETE_BATCH_SIZE) {
122	    const batch = keys.slice(i, i + DELETE_BATCH_SIZE);
123	    const result = await client.send(
124	      new DeleteObjectsCommand({
125	        Bucket: bucket,
126	        Delete: { Objects: batch.map((Key) => ({ Key })) },
127	      }),
128	    );
129	    deletedCount += result.Deleted?.length ?? 0;
130	    for (const error of result.Errors ?? []) {
131	      if (error.Key) {
132	        failedKeys.push(error.Key);
133	      }
134	    }
135	  }
136	
137	  if (failedKeys.length > 0) {
138	    throw new Error(`Failed to delete ${failedKeys.length} object(s): ${failedKeys.join(", ")}`);
139	  }
140	
141	  return deletedCount;
142	}
