144	export async function putFile(
145	  client: S3Client,
146	  bucket: string,
147	  slug: string,
148	  path: string,
149	  body: NonNullable<PutObjectCommandInput["Body"]>,
150	  contentType: string,
151	  uploadedBy: string,
152	  extraMetadata?: Record<string, string>,
153	): Promise<void> {
154	  await client.send(
155	    new PutObjectCommand({
156	      Bucket: bucket,
157	      Key: `${slug}/${path}`,
158	      Body: body,
159	      ContentType: contentType,
160	      CacheControl: "no-cache",
161	      Metadata: {
162	        "uploaded-by": uploadedBy,
163	        "uploaded-at": new Date().toISOString(),
164	        ...extraMetadata,
165	      },
166	    }),
167	  );
168	}
169	
170	export async function putThumbnail(
171	  client: S3Client,
172	  bucket: string,
173	  slug: string,
174	  image: Uint8Array,
175	): Promise<void> {
176	  await client.send(
177	    new PutObjectCommand({
178	      Bucket: bucket,
179	      Key: thumbnailKey(slug),
180	      Body: image,
181	      ContentType: "image/jpeg",
182	    }),
183	  );
184	}
185	
186	export async function getThumbnail(
187	  client: S3Client,
188	  bucket: string,
189	  slug: string,
190	): Promise<Uint8Array | undefined> {
191	  try {
192	    const result = await client.send(
193	      new GetObjectCommand({ Bucket: bucket, Key: thumbnailKey(slug) }),
194	    );
195	    return await result.Body?.transformToByteArray();
196	  } catch (err) {
197	    if (isNotFound(err)) {
198	      return undefined;
199	    }
200	    throw err;
201	  }
202	}
  1	import path from "node:path";
  2	import type { Readable } from "node:stream";
  3	import unzipper from "unzipper";
  4	
  5	export interface ZipEntry {
  6	  path: string;
  7	  content: Buffer;
  8	}
  9	
 10	export class ZipValidationError extends Error {}
 11	
 12	function normalizeEntryPath(rawPath: string): string {
 13	  if (rawPath.includes("\0")) {
 14	    throw new ZipValidationError(`Zip entry path contains a null byte: "${rawPath}"`);
 15	  }
 16	
 17	  const posixPath = rawPath.replace(/\\/g, "/");
 18	
 19	  if (path.posix.isAbsolute(posixPath)) {
 20	    throw new ZipValidationError(`Zip entry has an absolute path: "${rawPath}"`);
 21	  }
 22	
 23	  const normalized = path.posix.normalize(posixPath);
 24	  if (normalized === ".." || normalized.startsWith("../")) {
 25	    throw new ZipValidationError(`Zip entry escapes the archive root: "${rawPath}"`);
 26	  }
 27	
 28	  return normalized;
 29	}
 30	
 31	export function extractZip(source: Readable, maxTotalBytes: number): Promise<ZipEntry[]> {
 32	  const entries: ZipEntry[] = [];
 33	  let totalBytes = 0;
 34	
 35	  const zip = source.pipe(unzipper.Parse());
 36	
 37	  return new Promise<ZipEntry[]>((resolve, reject) => {
 38	    let settled = false;
 39	    const fail = (err: Error) => {
 40	      if (settled) {
 41	        return;
 42	      }
 43	      settled = true;
 44	      zip.destroy();
 45	      reject(err);
 46	    };
 47	
 48	    source.on("error", fail);
 49	
 50	    zip.on("entry", (entry: unzipper.Entry) => {
 51	      if (settled) {
 52	        entry.autodrain();
 53	        return;
 54	      }
 55	
 56	      if (entry.type === "Directory") {
 57	        entry.autodrain();
 58	        return;
 59	      }
 60	
 61	      let normalizedPath: string;
 62	      try {
 63	        normalizedPath = normalizeEntryPath(entry.path);
 64	      } catch (err) {
 65	        entry.autodrain();
 66	        fail(err as Error);
 67	        return;
 68	      }
 69	
 70	      const chunks: Buffer[] = [];
 71	      entry.on("data", (chunk: Buffer) => {
 72	        totalBytes += chunk.length;
 73	        if (totalBytes > maxTotalBytes) {
 74	          fail(new ZipValidationError(`Zip contents exceed the ${maxTotalBytes}-byte limit`));
 75	          return;
 76	        }
 77	        chunks.push(chunk);
 78	      });
 79	
 80	      entry.on("end", () => {
 81	        if (!settled) {
 82	          entries.push({ path: normalizedPath, content: Buffer.concat(chunks) });
 83	        }
 84	      });
 85	
 86	      entry.on("error", fail);
 87	    });
 88	
 89	    zip.on("close", () => {
 90	      if (!settled) {
 91	        settled = true;
 92	        resolve(entries);
 93	      }
 94	    });
 95	
 96	    zip.on("error", fail);
 97	  });
 98	}
 99	
100	const MACOS_JUNK_PATTERN = /(^|\/)(__MACOSX\/|\.DS_Store$|\._[^/]+$)/;
101	
102	/**
103	 * Drops macOS Finder zip artifacts (the `__MACOSX/` sidecar directory,
104	 * `.DS_Store`, and `._*` AppleDouble resource-fork files) that ride along
105	 * whenever someone zips a folder via Finder's "Compress" action.
106	 */
107	export function stripMacosJunk(entries: ZipEntry[]): ZipEntry[] {
108	  return entries.filter((entry) => !MACOS_JUNK_PATTERN.test(entry.path));
109	}
110	
111	/**
112	 * Collapses a single common wrapping directory (e.g. zipping a folder
113	 * itself, rather than its contents, produces every entry nested under
114	 * `<folder-name>/`) so `index.html` lands at the site root. Leaves entries
115	 * untouched unless every one of them shares the same top-level directory.
116	 */
117	export function stripCommonRoot(entries: ZipEntry[]): ZipEntry[] {
118	  const first = entries[0];
119	  if (!first) {
120	    return entries;
121	  }
122	
123	  const slashIndex = first.path.indexOf("/");
124	  if (slashIndex === -1) {
125	    return entries;
126	  }
127	
128	  const prefix = first.path.slice(0, slashIndex + 1);
129	  if (!entries.every((entry) => entry.path.startsWith(prefix))) {
130	    return entries;
131	  }
132	
133	  return entries
134	    .map((entry) => ({ ...entry, path: entry.path.slice(prefix.length) }))
135	    .filter((entry) => entry.path.length > 0);
136	}
137	
138	const ROOT_HTML_PATTERN = /^[^/]+\.html?$/i;
139	
140	export interface PromoteIndexResult {
141	  entries: ZipEntry[];
142	  aliasedIndexFrom?: string;
143	}
144	
145	/**
146	 * When a zip has no root `index.html` but exactly one root-level `.html`
147	 * file, aliases that file's content as `index.html` too — LLM-generated
148	 * single-page output is rarely named `index.html` (e.g. `art-history-quiz.html`).
149	 * Adds a second copy rather than renaming, so the original filename (and any
150	 * links to it) keeps working. Left alone when there's more than one root
151	 * `.html` file, since there's no way to guess the intended entry point.
152	 */
153	export function promoteSoleRootHtmlToIndex(entries: ZipEntry[]): PromoteIndexResult {
154	  if (entries.some((entry) => entry.path === "index.html")) {
155	    return { entries };
156	  }
157	
158	  const rootHtmlEntries = entries.filter((entry) => ROOT_HTML_PATTERN.test(entry.path));
159	  const sole = rootHtmlEntries.length === 1 ? rootHtmlEntries[0] : undefined;
160	  if (!sole) {
161	    return { entries };
162	  }
163	
164	  return {
165	    entries: [...entries, { path: "index.html", content: sole.content }],
166	    aliasedIndexFrom: sole.path,
167	  };
168	}
169	
170	/** Prepares raw `extractZip` output for upload: strip macOS junk, collapse a common wrapping folder, then alias a sole root .html file as index.html if needed. */
171	export function normalizeZipEntries(entries: ZipEntry[]): PromoteIndexResult {
172	  return promoteSoleRootHtmlToIndex(stripCommonRoot(stripMacosJunk(entries)));
173	}
