 26	export function validateSlug(slug: string): SlugValidationResult {
 27	  if (!SLUG_PATTERN.test(slug)) {
 28	    return {
 29	      valid: false,
 30	      error:
 31	        "Slug must be lowercase alphanumeric with hyphens, 1-63 characters, and cannot start or end with a hyphen",
 32	    };
 33	  }
 34	
 35	  if (RESERVED_SLUGS.has(slug)) {
 36	    return { valid: false, error: `Slug "${slug}" is reserved` };
