  3	import { headIndex, listSlugs } from "./s3";
  4	
  5	export interface SiteInfo {
  6	  slug: string;
  7	  uploadedBy?: string;
  8	  uploadedAt?: string;
  9	}
 10	
 11	export type SiteSort = "name" | "oldest" | "newest" | "uploader";
 12	
 13	export async function listSites(
 14	  client: S3Client,
 15	  bucket: string,
 16	  sort: SiteSort = "name",
 17	): Promise<SiteInfo[]> {
 18	  const slugs = await listSlugs(client, bucket);
 19	  const sites = await Promise.all(
 20	    slugs.map(async (slug): Promise<SiteInfo> => {
 21	      const { uploadedBy, uploadedAt } = await headIndex(client, bucket, slug);
 22	      return {
 23	        slug,
 24	        ...(uploadedBy !== undefined && { uploadedBy }),
 25	        ...(uploadedAt !== undefined && { uploadedAt }),
 26	      };
 27	    }),
 28	  );
 29	
 30	  return sortSites(sites, sort);
 31	}
 32	
 33	// Missing values sort last, in either direction.
 34	function compareDates(a: SiteInfo, b: SiteInfo, direction: 1 | -1): number {
 35	  if (a.uploadedAt === undefined) {
 36	    return b.uploadedAt === undefined ? 0 : 1;
 37	  }
 38	  if (b.uploadedAt === undefined) {
 39	    return -1;
 40	  }
 41	  return direction * a.uploadedAt.localeCompare(b.uploadedAt);
 42	}
 43	
 44	// Anonymous and absent uploaders count as missing, and ties go to the
 45	// newest upload, so one person's sites read most-recent first.
 46	function compareUploaders(a: SiteInfo, b: SiteInfo): number {
 47	  const x = formatUploader(a.uploadedBy);
 48	  const y = formatUploader(b.uploadedBy);
 49	  if (x === null || y === null) {
 50	    return x === y ? compareDates(a, b, -1) : x === null ? 1 : -1;
 51	  }
 52	  return x.localeCompare(y, "en", { sensitivity: "base" }) || compareDates(a, b, -1);
 53	}
 54	
 55	export function sortSites(sites: SiteInfo[], sort: SiteSort): SiteInfo[] {
 56	  const copy = [...sites];
 57	
 58	  switch (sort) {
 59	    case "oldest":
 60	      copy.sort((a, b) => compareDates(a, b, 1));
 61	      break;
 62	    case "newest":
 63	      copy.sort((a, b) => compareDates(a, b, -1));
 64	      break;
 65	    case "uploader":
 66	      copy.sort(compareUploaders);
 67	      break;
 68	    default:
 69	      copy.sort((a, b) => a.slug.localeCompare(b.slug));
 70	  }
 71	
 72	  return copy;
 73	}
