 31	export function extractZip(source: Readable, maxTotalBytes: number): Promise<ZipEntry[]> {
 32	  const entries: ZipEntry[] = [];
 33	  let totalBytes = 0;
 34	
 35	  const zip = source.pipe(unzipper.Parse());
 36	
 37	  return new Promise<ZipEntry[]>((resolve, reject) => {
 38	    let settled = false;
 39	    const fail = (err: Error) => {
 40	      if (settled) {
 41	        return;
 42	      }
 43	      settled = true;
 44	      zip.destroy();
 45	      reject(err);
 46	    };
 47	
 48	    source.on("error", fail);
 49	
 50	    zip.on("entry", (entry: unzipper.Entry) => {
 51	      if (settled) {
 52	        entry.autodrain();
 53	        return;
 54	      }
 55	
 56	      if (entry.type === "Directory") {
 57	        entry.autodrain();
 58	        return;
 59	      }
 60	
 61	      let normalizedPath: string;
 62	      try {
 63	        normalizedPath = normalizeEntryPath(entry.path);
 64	      } catch (err) {
 65	        entry.autodrain();
 66	        fail(err as Error);
 67	        return;
 68	      }
 69	
 70	      const chunks: Buffer[] = [];
 71	      entry.on("data", (chunk: Buffer) => {
 72	        totalBytes += chunk.length;
 73	        if (totalBytes > maxTotalBytes) {
 74	          fail(new ZipValidationError(`Zip contents exceed the ${maxTotalBytes}-byte limit`));
 75	          return;
 76	        }
 77	        chunks.push(chunk);
 78	      });
 79	
 80	      entry.on("end", () => {
 81	        if (!settled) {
 82	          entries.push({ path: normalizedPath, content: Buffer.concat(chunks) });
 83	        }
 84	      });
 85	
 86	      entry.on("error", fail);
 87	    });
 88	
 89	    zip.on("close", () => {
 90	      if (!settled) {
 91	        settled = true;
 92	        resolve(entries);
 93	      }
 94	    });
 95	
 96	    zip.on("error", fail);
 97	  });
 98	}
