100	const MACOS_JUNK_PATTERN = /(^|\/)(__MACOSX\/|\.DS_Store$|\._[^/]+$)/;
101	
102	/**
103	 * Drops macOS Finder zip artifacts (the `__MACOSX/` sidecar directory,
104	 * `.DS_Store`, and `._*` AppleDouble resource-fork files) that ride along
105	 * whenever someone zips a folder via Finder's "Compress" action.
106	 */
107	export function stripMacosJunk(entries: ZipEntry[]): ZipEntry[] {
108	  return entries.filter((entry) => !MACOS_JUNK_PATTERN.test(entry.path));
109	}
110	
111	/**
112	 * Collapses a single common wrapping directory (e.g. zipping a folder
113	 * itself, rather than its contents, produces every entry nested under
114	 * `<folder-name>/`) so `index.html` lands at the site root. Leaves entries
115	 * untouched unless every one of them shares the same top-level directory.
116	 */
117	export function stripCommonRoot(entries: ZipEntry[]): ZipEntry[] {
118	  const first = entries[0];
119	  if (!first) {
120	    return entries;
121	  }
122	
123	  const slashIndex = first.path.indexOf("/");
124	  if (slashIndex === -1) {
125	    return entries;
126	  }
127	
128	  const prefix = first.path.slice(0, slashIndex + 1);
129	  if (!entries.every((entry) => entry.path.startsWith(prefix))) {
130	    return entries;
131	  }
132	
133	  return entries
134	    .map((entry) => ({ ...entry, path: entry.path.slice(prefix.length) }))
135	    .filter((entry) => entry.path.length > 0);
136	}
