145	/**
146	 * When a zip has no root `index.html` but exactly one root-level `.html`
147	 * file, aliases that file's content as `index.html` too — LLM-generated
148	 * single-page output is rarely named `index.html` (e.g. `art-history-quiz.html`).
149	 * Adds a second copy rather than renaming, so the original filename (and any
150	 * links to it) keeps working. Left alone when there's more than one root
151	 * `.html` file, since there's no way to guess the intended entry point.
152	 */
153	export function promoteSoleRootHtmlToIndex(entries: ZipEntry[]): PromoteIndexResult {
154	  if (entries.some((entry) => entry.path === "index.html")) {
155	    return { entries };
156	  }
