 11	const RESERVED_SLUGS = new Set([
 12	  "atelier",
 13	  "atelier-staging",
 14	  "www",
 15	  "staging",
 16	  "api",
 17	  "api-staging",
 18	  "upload",
 19	  "uploads",
 20	  "gallery",
 21	  "upload-staging",
 22	  "admin",
 23	  "admin-staging",
 24	]);
